{
  "sop_id": "SOP-015",
  "title": "Invoice Verification (Three-Way Match)",
  "steps": [
    {
      "step_id": "S1",
      "name": "Create and assign ticket",
      "role": "Executor",
      "type": "intake"
    },
    {
      "step_id": "S2",
      "name": "Validate vendor's GSTIN and PAN, and check for duplicates",
      "role": "Executor",
      "type": "work"
    },
    {
      "step_id": "S3",
      "name": "Match invoice, PO, and GRN line by line",
      "role": "Executor",
      "type": "work"
    },
    {
      "step_id": "S4",
      "name": "Compute GST input credit and TDS",
      "role": "Executor",
      "type": "work"
    },
    {
      "step_id": "S5",
      "name": "Adjust advances and other deductions",
      "role": "Executor",
      "type": "work"
    },
    {
      "step_id": "S6",
      "name": "Prepare the payment voucher and submit",
      "role": "Executor",
      "type": "work"
    },
    {
      "step_id": "D1",
      "name": "Wait for GRN or completion certificate confirmation",
      "role": "System",
      "type": "intake"
    },
    {
      "step_id": "A1",
      "name": "Incharge verification and approval",
      "role": "Incharge",
      "type": "approval"
    },
    {
      "step_id": "A2",
      "name": "Lead approval (for out-of-tolerance or high-value invoices)",
      "role": "Lead",
      "type": "approval"
    },
    {
      "step_id": "R1",
      "name": "Correct and resubmit after rejection",
      "role": "Executor",
      "type": "rework"
    }
  ],
  "approvals": [
    {
      "stage": "Incharge",
      "condition": "always"
    },
    {
      "stage": "Lead",
      "condition": "if invoice is out-of-tolerance or high-value"
    }
  ],
  "dependencies": [
    {
      "dep_id": "D1",
      "provider": "Stores",
      "item": "GRN or completion certificate",
      "parallel_group": "P1"
    }
  ],
  "rework_reasons": [
    "Amount mismatch",
    "Wrong quantity",
    "Incorrect category",
    "Required document missing"
  ],
  "first_pass_yield_target": 0.90
}
